import json, pathlib
ROOT=pathlib.Path(__file__).parent

def S(id,title,pages,intro,points,remember,table=None,formula=None):
    out=dict(id=id,title=title,pages=f'หน้า {pages}',intro=intro,points=points,remember=remember)
    if table:out['table']=dict(headers=['คำศัพท์ / องค์ประกอบ','ความหมาย / จุดสังเกต'],rows=table)
    if formula:out['formula']=formula
    return out

def G(topic,term,definition):return dict(topic=topic,term=term,definition=definition)

def Q(topic,prompt,options,answer,explanations,level='ประยุกต์'):
    assert len(options)==len(explanations)==4 and 0<=answer<4
    return dict(topic=topic,prompt=prompt,options=options,answer=answer,reasons=explanations,level=level)

