# Build consistent flashcards, randomized-correct-position MCQs and reasoned distractors.
result=[]
for ch in chs:
    cards=ch.pop('gloss')
    extras=ch.pop('extra')
    keys={s['id'] for s in ch['sections']}
    assert len(keys)==len(ch['sections'])
    for c in cards:assert c['topic'] in keys and len(c['definition'])>20
    flashcards=[dict(id=f"ch{ch['number']}-f{i+1}",front=f"{c['term']} คืออะไร?",back=c['definition'],term=c['term'],meaning=c['definition']) for i,c in enumerate(cards)]
    questions=[]
    for i,c in enumerate(cards):
        # Take distractors from other concepts to avoid duplicated option text.
        alternatives=[cards[(i+offset)%len(cards)] for offset in [3,7,11]]
        alternatives=[a for a in alternatives if a['term']!=c['term']]
        if len(alternatives)<3:
            alternatives=[a for a in cards if a['term']!=c['term']][:3]
        correct_index=(i*3 + ch['number'])%4
        ordered=alternatives[:3];ordered.insert(correct_index,c)
        questions.append(dict(id=f"ch{ch['number']}-q{i+1}",topic=c['topic'],level='เข้าใจ',
          prompt=f"ข้อใดอธิบาย “{c['term']}” ได้ถูกต้องที่สุด?",
          options=[a['definition'] for a in ordered], answer=correct_index,
          reasons=[f"ถูกต้อง: {c['term']} หมายถึง {a['definition']}" if j==correct_index else f"ไม่ใช่: นิยามนี้เป็นของ {a['term']} ไม่ใช่ {c['term']}" for j,a in enumerate(ordered)]))
    for i,q in enumerate(extras):
        q['id']=f"ch{ch['number']}-q{len(questions)+i+1}"
        questions.append(q)
    assert all(q['topic'] in keys and len(q['options'])==4 and len(q['reasons'])==4 and all(q['reasons']) for q in questions)
    ch['source']=f"สรุปและแบบฝึกหัดเรียบเรียงจาก mm169_ch{ch['number']}.pdf · Multimedia Technology · Semester 1/2026 · IT KMITL · เลขหน้าเป็นลำดับหน้า PDF"
    ch['exam']='final'
    ch['flashcards']=flashcards
    ch['questions']=questions
    result.append(ch)

